<script lang="ts">
  import { ArrowRight, ArrowUpRight, Check, Compass, Sunrise } from '@lucide/svelte';
  import { Button } from '$lib/components/ui/button';
  import GuestReviews from './guest-reviews.svelte';
  import * as Tabs from '$lib/components/ui/tabs';
  import { costRows, guideRows, sectionDefault, type GuestReview } from '$lib/homepage-guides';
  import { safeUrl, textContent } from '$lib/home-content';
  import type { HomepageSection } from '$lib/types/api';
  let { section, canEnquire, onInterest = () => {}, reviews = [] }: { section: HomepageSection; canEnquire: boolean; onInterest?: (interest: string) => void; reviews?: GuestReview[] } = $props();
  let rows = $derived(guideRows(section));
  let costs = $derived(costRows(section));
  let selected = $state('0');
  let note = $derived(textContent(String(section.extra_data?.note ?? sectionDefault(section.section_key)?.extra_data?.note ?? '')));
  let photo = $derived(safeUrl(section.image_url, sectionDefault(section.section_key)?.image_url || '/images/serengeti.jpg'));
  let cta = $derived(safeUrl(section.button_url));
</script>

{#if section.section_key !== 'reviews_section' || reviews.length}
<section id={section.section_key.replaceAll('_', '-')} class:cost-band={section.section_key === 'cost_ranges'} class:day-band={section.section_key === 'safari_day'} class="safari-guide" class:reviews-band={section.section_key === 'reviews_section'} aria-labelledby={`${section.section_key}-heading`}>
  <div class="page-container">
    <div class="guide-heading" data-motion="reveal"><p class="eyebrow">{section.subtitle}</p><h2 id={`${section.section_key}-heading`} class="section-heading">{section.title}</h2><p class="section-description">{textContent(section.content)}</p></div>

    {#if section.section_key === 'why_tanzania'}
      <div class="country-grid"><div class="country-photo" data-motion="image"><img src={photo} alt="Tanzania’s dramatic safari landscape" loading="lazy"/><span><Compass size={18}/> Tanzania, at your own pace.</span></div><div class="country-reasons">{#each rows as row}<article data-motion="reveal"><span class="number">{row.label}</span><div><h3>{row.title}</h3><p>{row.text}</p></div></article>{/each}</div></div>
    {:else if section.section_key === 'cost_ranges'}
      <div class="cost-grid">{#each costs as row, i}<article data-motion="card" class:highlight={i === 1}><div class="cost-top"><span class="eyebrow">{String(i + 1).padStart(2,'0')} / YOUR TRAVEL STYLE</span><Compass size={22}/></div><h3>{row.label}</h3><p class="cost-price">{row.from || 'Ask for a quote'}</p><p class="cost-copy">{row.note}</p>{#if canEnquire}<Button href={cta} variant={i === 1 ? 'safari' : 'outline'} class="mt-auto w-full" onclick={() => onInterest(`${row.label} safari`)}>Explore {row.label.toLowerCase()} <ArrowUpRight size={16}/></Button>{/if}</article>{/each}</div>
      <div class="guide-foot"><p>{note}</p>{#if canEnquire}<Button href={cta} variant="safari" onclick={() => onInterest('Help planning my safari budget')}>{section.button_text || 'Plan around my budget'}<ArrowRight size={16}/></Button>{/if}</div>
    {:else if section.section_key === 'safari_duration'}
      {#if rows.length}<div class="duration-layout"><Tabs.Root bind:value={selected}><Tabs.List aria-label="Choose your safari length" class="duration-tabs">{#each rows as row,i}<Tabs.Trigger value={String(i)} class="duration-tab">{row.label || row.title}</Tabs.Trigger>{/each}</Tabs.List><div class="duration-content"><img src={photo} alt="A safari vehicle exploring Tanzania" loading="lazy"/>{#each rows as row,i}<Tabs.Content value={String(i)} class="duration-panel"><span class="eyebrow">{row.label} / YOUR JOURNEY</span><h3>{row.title}</h3><p>{row.text}</p>{#if canEnquire}<Button href={cta} variant="safari" onclick={() => onInterest(`${row.label} Tanzania safari`)}>{section.button_text || 'Plan this journey'}<ArrowRight size={16}/></Button>{/if}</Tabs.Content>{/each}</div></Tabs.Root></div>{/if}
    {:else if section.section_key === 'safari_inclusions'}
      <div class="inclusion-grid">{#each rows as row}<article data-motion="reveal"><span class="check-icon"><Check size={19}/></span><div><span class="eyebrow">{row.label}</span><h3>{row.title}</h3><p>{row.text}</p></div></article>{/each}</div>{#if note}<aside class="exclusions"><span class="eyebrow">PLAN FOR THE EXTRAS</span><p>{note}</p></aside>{/if}
    {:else if section.section_key === 'safari_day'}
      <div class="day-layout"><div class="day-photo" data-motion="image"><img src={photo} alt="Golden evening light over the Tanzanian landscape" loading="lazy"/><div><Sunrise size={30}/><p>Slow moments.<br/>Extraordinary memories.</p></div></div><ol class="day-timeline">{#each rows as row}<li data-motion="reveal"><span class="day-time">{row.label}</span><div><h3>{row.title}</h3><p>{row.text}</p></div></li>{/each}</ol></div>
    {:else if section.section_key === 'reviews_section'}
      <GuestReviews {reviews} />
    {/if}
  </div>
</section>
{/if}

